let toastTimer;function toast(message){const box=document.querySelector('.toast');if(!box)return;clearTimeout(toastTimer);box.textContent=message;box.hidden=false;toastTimer=setTimeout(()=>box.hidden=true,4500)}
function openDialog(id){const d=document.getElementById(id);if(!d)return;d.showModal();d.dataset.opener='active'}
function closePopovers(){document.querySelectorAll('[data-popover][aria-expanded=true]').forEach(b=>{b.setAttribute('aria-expanded','false');b.nextElementSibling.hidden=true})}
function commandSearch(query=''){const links=[{name:'Overview',category:'Get started',route:'overview'},{name:'Installation & usage',category:'Get started',route:'usage'},...foundationLinks.map(([r,name])=>({name,category:'Foundations',route:'foundations-'+r})),...catalog.map(c=>({name:c.name,category:categories[c.category],route:'components-'+c.category,id:c.id})),...patternLinks.map(([r,name])=>({name,category:'Patterns',route:'patterns-'+r}))].filter(x=>(x.name+' '+x.category).toLowerCase().includes(query.toLowerCase()));document.getElementById('command-results').innerHTML=links.length?links.map(x=>`<a href="#${x.route}" data-search-target="${x.id||''}">${x.name}<small>${x.category}</small></a>`).join(''):'<p class="small">No matches. Try a component name like “button”.</p>'}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(e.target.closest('[data-close-nav]'))closeNav();if(!e.target.closest('.popover-wrap'))closePopovers();if(!b)return;
if(b.matches('[data-open-nav]')){const side=document.querySelector('.docs-sidebar');side.classList.toggle('open');document.querySelector('.mobile-backdrop').hidden=!side.classList.contains('open');b.setAttribute('aria-expanded',side.classList.contains('open'));if(side.classList.contains('open'))side.querySelector('a').focus()}
if(b.hasAttribute('data-command')){commandSearch();document.getElementById('command-input').value='';openDialog('command-dialog');document.getElementById('command-input').focus()}
if(b.hasAttribute('data-search-target')){document.getElementById('command-dialog').close();const target=b.dataset.searchTarget;setTimeout(()=>{document.getElementById(target)?.scrollIntoView({block:'start'});},40)}
if(b.hasAttribute('data-route-go'))location.hash=b.dataset.routeGo;
if(b.hasAttribute('data-toast'))toast(b.dataset.toast);
if(b.hasAttribute('data-modal'))openDialog(b.dataset.modal+'-dialog');
if(b.hasAttribute('data-confirm'))openDialog('confirm-dialog');
if(b.hasAttribute('data-close-dialog'))b.closest('dialog').close();
if(b.hasAttribute('data-delete-confirm')){b.closest('dialog').close();toast('Demo project deleted')}
if(b.hasAttribute('data-reveal')){const input=b.parentElement.querySelector('input');const show=input.type==='password';input.type=show?'text':'password';b.setAttribute('aria-pressed',show);b.setAttribute('aria-label',show?'Hide password':'Show password')}
if(b.hasAttribute('data-chip')){b.setAttribute('aria-pressed',b.getAttribute('aria-pressed')!=='true')}
if(b.hasAttribute('data-choice')){b.parentElement.querySelectorAll('[data-choice]').forEach(x=>{const selected=x===b;x.setAttribute('aria-pressed',selected);x.classList.toggle('tertiary',selected);x.classList.toggle('secondary',!selected)});const out=b.parentElement.parentElement.querySelector('[data-choice-output]');if(out)out.textContent=b.textContent+' view selected.'}
if(b.matches('[role=tab]')){const group=b.closest('[data-tabs]');group.querySelectorAll('[role=tab]').forEach(t=>{t.setAttribute('aria-selected',t===b);t.tabIndex=t===b?0:-1;document.getElementById(t.getAttribute('aria-controls')).hidden=t!==b})}
if(b.hasAttribute('data-popover')){const open=b.getAttribute('aria-expanded')==='true';closePopovers();b.setAttribute('aria-expanded',!open);b.nextElementSibling.hidden=open;if(!open)b.nextElementSibling.querySelector('button')?.focus()}
if(b.hasAttribute('data-dismiss-banner'))b.closest('.banner').remove();
if(b.hasAttribute('data-loading')){const original=b.innerHTML;b.disabled=true;b.setAttribute('aria-busy','true');b.innerHTML='<span class="spinner" aria-hidden="true"></span> Saving…';setTimeout(()=>{b.innerHTML=original;b.disabled=false;b.removeAttribute('aria-busy');toast('Changes saved')},1000)}
if(b.hasAttribute('data-view-code')){const code=document.getElementById(b.dataset.viewCode);code.hidden=!code.hidden;b.setAttribute('aria-expanded',!code.hidden)}
if(b.hasAttribute('data-copy')){const html=catalog[Number(b.dataset.copy)].html.replaceAll('__ID__','example');try{await navigator.clipboard.writeText(html);toast('HTML copied to clipboard')}catch{const code=b.closest('.component-card').querySelector('pre');code.hidden=false;const range=document.createRange();range.selectNodeContents(code);const sel=getSelection();sel.removeAllRanges();sel.addRange(range);toast('Select and copy the highlighted HTML')}}
if(b.hasAttribute('data-page')){const group=b.closest('[data-pagination]');let n=Number(group.dataset.current||1);n=b.dataset.page==='next'?n+1:b.dataset.page==='prev'?n-1:Number(b.dataset.page);n=Math.max(1,Math.min(3,n));group.dataset.current=n;group.querySelectorAll('[data-page]').forEach(x=>{const current=Number(x.dataset.page)===n;current?x.setAttribute('aria-current','page'):x.removeAttribute('aria-current');x.classList.toggle('tertiary',current);if(x.dataset.page==='prev')x.disabled=n===1;if(x.dataset.page==='next')x.disabled=n===3});group.querySelector('[data-page-output]').textContent=`Page ${n} of 3 · Items ${(n-1)*10+1}–${n*10}`}
if(b.hasAttribute('data-mark-read')){b.textContent='All caught up';b.disabled=true}
if(b.hasAttribute('data-export')){const rows=[['Name','Role','Status'],...Array.from(b.closest('.card').querySelectorAll('tbody tr')).filter(r=>{const all=b.closest('.card').querySelectorAll('[data-row-check]:checked');return !all.length||r.querySelector('[data-row-check]').checked}).map(r=>Array.from(r.querySelectorAll('td')).slice(1).map((c,i)=>i===0?(c.querySelector('.inline > span:last-child')?.textContent.trim()||c.textContent.trim()):c.textContent.trim()))];const blob=new Blob([rows.map(r=>r.map(v=>'"'+v.replaceAll('"','""')+'"').join(',')).join('\n')],{type:'text/csv'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='forma-team.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Team CSV exported')}
});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='command-input')commandSearch(el.value);if(el.matches('[data-range]'))el.parentElement.querySelector('output').textContent=el.value+'%';if(el.matches('[data-counter]'))el.parentElement.querySelector('[data-count]').textContent=el.value.length+' / 500 characters';if(el.matches('[data-demo-search]')){const group=el.closest('.preview-pane,.card,.showcase-body');let count=0;group.querySelectorAll('[data-search-list] li').forEach(li=>{li.hidden=!li.textContent.toLowerCase().includes(el.value.toLowerCase());if(!li.hidden)count++});group.querySelector('[data-search-status]').textContent=count?`${count} matching project${count===1?'':'s'}`:'No projects match your search.'}if(el.closest('.otp')){el.value=el.value.replace(/\D/g,'').slice(-1);if(el.value)el.nextElementSibling?.focus()}});
document.addEventListener('change',e=>{const el=e.target;if(el.matches('[data-file]'))el.parentElement.querySelector('[data-file-status]').textContent=el.files.length?Array.from(el.files).map(f=>f.name).join(', '):'No file selected';if(el.matches('[data-select-all],[data-row-check]')){const group=el.closest('.preview-pane,.card');const all=group.querySelector('[data-select-all]'),rows=[...group.querySelectorAll('[data-row-check]')];if(el===all)rows.forEach(x=>x.checked=all.checked);const count=rows.filter(x=>x.checked).length;all.checked=count===rows.length;all.indeterminate=count>0&&count<rows.length;group.querySelector('[data-selection-status]').textContent=`${count} members selected`}});
document.addEventListener('submit',e=>{const form=e.target;if(!form.matches('[data-demo-form]'))return;e.preventDefault();if(!form.reportValidity())return;toast(form.dataset.demoForm);form.closest('dialog')?.close()});
document.addEventListener('paste',e=>{if(!e.target.closest('.otp'))return;const digits=e.clipboardData.getData('text').replace(/\D/g,'').slice(0,6);if(!digits)return;e.preventDefault();const inputs=[...e.target.closest('.otp').querySelectorAll('input')];inputs.forEach((el,i)=>el.value=digits[i]||'');inputs[Math.min(digits.length,5)].focus()});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();commandSearch();openDialog('command-dialog');document.getElementById('command-input').focus()}if(e.key==='Escape'){const open=document.querySelector('[data-popover][aria-expanded=true]');closePopovers();open?.focus();closeNav()}if(e.target.matches('[role=tab]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...e.target.parentElement.querySelectorAll('[role=tab]')];let i=tabs.indexOf(e.target);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[i].click();tabs[i].focus()}if(e.target.closest('.otp')){if(e.key==='Backspace'&&!e.target.value)e.target.previousElementSibling?.focus();if(e.key==='ArrowLeft')e.target.previousElementSibling?.focus();if(e.key==='ArrowRight')e.target.nextElementSibling?.focus()}});
